from pathlib import Path
import py_compile, shutil, sys
p=Path(sys.argv[1] if len(sys.argv)>1 else "app.py")
backup=p.with_name(p.name+".before_global_no_overlap_v23.bak")
marker="# MARSIP GLOBAL NO OVERLAP V23"
if not p.is_file(): raise SystemExit(f"Missing {p}")
s=p.read_text(encoding="utf-8")
if marker in s:
    print("Global no-overlap V23 is already installed.")
    raise SystemExit(0)
patch='\n\n# MARSIP GLOBAL NO OVERLAP V23\n# Presentation-only. No database or billing logic changes.\n@app.after_request\ndef marsip_global_no_overlap_v23(response):\n    if response.status_code != 200 or \'text/html\' not in response.headers.get(\'Content-Type\', \'\'):\n        return response\n    html = response.get_data(as_text=True)\n    if \'marsip-global-no-overlap-v23\' in html:\n        return response\n    addition = r\'\'\'<style id="marsip-global-no-overlap-v23">\n*,*::before,*::after{box-sizing:border-box!important}\nmain,section,article,form,fieldset,.card,.cards,.grid{min-width:0!important;max-width:100%!important}\n.grid,.marsip-responsive-form-v23{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr))!important;gap:16px 14px!important;align-items:start!important;width:100%!important}\n.grid>*,.marsip-responsive-form-v23>*{min-width:0!important;max-width:100%!important;width:auto!important;margin:0!important}\nlabel{min-width:0!important;max-width:100%!important}\ninput:not([type="checkbox"]):not([type="radio"]),select,textarea{display:block!important;width:100%!important;min-width:0!important;max-width:100%!important;box-sizing:border-box!important}\ntextarea{min-height:92px!important;resize:vertical!important;white-space:pre-wrap!important;word-break:normal!important;overflow-wrap:break-word!important}\n.marsip-wide-field-v23{grid-column:span 2!important;min-width:0!important}.marsip-wide-field-v23 textarea{min-height:110px!important}\n.marsip-number-field-v23{min-width:130px!important;max-width:180px!important}.marsip-number-field-v23 input,.marsip-number-field-v23 select{min-width:0!important}\n.actions,.toolbar,.page-head,.sticky-actions,.marsip-actions-v23{display:flex!important;flex-wrap:wrap!important;gap:10px!important;min-width:0!important;max-width:100%!important}\nbutton,.button,input[type="submit"]{max-width:100%!important;white-space:normal!important}\n.wide,.table-scroll,.table-wrapper,.table-responsive{width:100%!important;max-width:100%!important;min-width:0!important;overflow-x:auto!important;-webkit-overflow-scrolling:touch!important}\ntd,th{word-break:normal!important;overflow-wrap:break-word!important;vertical-align:top!important}\ntd input:not([type="checkbox"]):not([type="radio"]),td select,td textarea{width:100%!important;min-width:0!important;max-width:100%!important}\n.marsip-add-line-v23{display:grid!important;grid-template-columns:minmax(170px,.8fr) minmax(280px,2fr) minmax(135px,.65fr) minmax(135px,.65fr)!important;gap:16px 14px!important;align-items:start!important;width:100%!important}\n.marsip-add-line-v23>*{min-width:0!important;max-width:100%!important}.marsip-add-line-v23 textarea{min-height:105px!important}\n@media(max-width:1050px){.marsip-add-line-v23{grid-template-columns:repeat(2,minmax(0,1fr))!important}.marsip-wide-field-v23{grid-column:1/-1!important}}\n@media(max-width:680px){.grid,.marsip-responsive-form-v23,.marsip-add-line-v23{grid-template-columns:1fr!important}.marsip-wide-field-v23{grid-column:auto!important}.marsip-number-field-v23{max-width:100%!important}}\n</style>\n<script id="marsip-global-no-overlap-script-v23">\n(()=>{const txt=e=>(e.textContent||\'\').replace(/\\s+/g,\' \').trim().toLowerCase();const wide=[\'description\',\'service description\',\'services\',\'billing address\',\'custom vat wording\',\'telecom description\',\'annex text\',\'notes\'];const nums=[\'quantity/hours\',\'quantity\',\'hours\',\'rate\',\'vat rate\',\'net amount\',\'amount\',\'worked\',\'billable\'];document.querySelectorAll(\'form .grid\').forEach(g=>{g.classList.add(\'marsip-responsive-form-v23\');const labels=[...g.children].filter(e=>e.tagName===\'LABEL\');labels.forEach(l=>{const t=txt(l);if(wide.some(x=>t.startsWith(x))||l.querySelector(\'textarea\'))l.classList.add(\'marsip-wide-field-v23\');if(nums.some(x=>t.startsWith(x)))l.classList.add(\'marsip-number-field-v23\')});const add=labels.some(l=>txt(l).startsWith(\'type\'))&&labels.some(l=>txt(l).startsWith(\'description\'))&&labels.some(l=>txt(l).startsWith(\'quantity\'));if(add)g.classList.add(\'marsip-add-line-v23\')})})();\n</script>\'\'\'\n    html = html.replace(\'</body>\', addition + \'</body>\', 1) if \'</body>\' in html else html + addition\n    response.set_data(html)\n    response.headers[\'Content-Length\'] = len(response.get_data())\n    return response\n'
shutil.copy2(p,backup)
p.write_text(s.rstrip()+patch+"\n",encoding="utf-8")
try: py_compile.compile(str(p),doraise=True)
except Exception:
    shutil.copy2(backup,p)
    print("Validation failed. Original app.py restored.")
    raise
print("Global no-overlap V23 installed.")
print("Rollback:",backup)
print("Syntax validation passed.")
